<?php
namespace App\Http\Controllers\Accounting;use App\Http\Controllers\Controller;use App\Models\{Account,JournalEntry};use App\Services\Accounting\AccountingService;use Illuminate\Http\Request;
class JournalController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('accounting.journals',['rows'=>JournalEntry::with('lines.account')->where('property_id',$p)->latest()->paginate(30),'accounts'=>Account::where('property_id',$p)->where('is_active',1)->orderBy('code')->get()]);}public function store(Request $r,AccountingService $svc){$d=$r->validate(['entry_date'=>'required|date','description'=>'required|max:255','debit_account_id'=>'required|integer','credit_account_id'=>'required|integer|different:debit_account_id','amount'=>'required|numeric|min:.01']);$p=auth()->user()->property_id;$accounts=Account::where('property_id',$p)->whereIn('id',[$d['debit_account_id'],$d['credit_account_id']])->get()->keyBy('id');abort_unless($accounts->count()===2,403);$svc->post($p,'manual',null,$d['description'],[['account'=>$accounts[$d['debit_account_id']],'debit'=>$d['amount']],['account'=>$accounts[$d['credit_account_id']],'credit'=>$d['amount']]],auth()->id());return back()->with('success','Journal entry posted.');}}
